<?php

declare(strict_types=1);

require_once __DIR__.'/Database.php';
require_once __DIR__.'/Auth.php';
require_once __DIR__.'/AppNavigation.php';
require_once __DIR__.'/AccessPolicy.php';
require_once __DIR__.'/DynamicFormService.php';

final class DynamicFormExperience
{
    private const ROUTES=['/admin/forms/builder','/forms/view','/admin/forms/review'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();
        $db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user)self::redirect(($basePath?:'').'/login');$_SESSION['dynamic_forms_csrf']??=bin2hex(random_bytes(24));
        if($route==='/admin/forms/builder'){
            if(!AccessPolicy::isStaff($user))self::forbidden($basePath,$user);
            $formId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'form_id',FILTER_VALIDATE_INT)?:0;$form=self::form($db,(int)$formId);
            if($_SERVER['REQUEST_METHOD']==='POST')self::handleBuilderPost($db,$user,(int)$formId,$basePath);
            self::builderPage($db,$basePath,$user,$form);
        }
        if($route==='/forms/view'){
            $assignmentId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'assignment_id',FILTER_VALIDATE_INT)?:0;$assignment=self::assignment($db,(int)$user['id'],(int)$assignmentId);
            if(!$assignment||!DynamicFormService::fields($db,(int)$assignment['form_id']))self::delegateLegacy($route,$basePath);
            if($_SERVER['REQUEST_METHOD']==='POST')self::handleSubmit($db,$user,(int)$assignmentId,$basePath);
            self::fillPage($db,$basePath,$user,$assignment);
        }
        if($route==='/admin/forms/review'){
            if(!AccessPolicy::isStaff($user))self::forbidden($basePath,$user);
            $submissionId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'submission_id',FILTER_VALIDATE_INT)?:0;$review=self::reviewItem($db,(int)$submissionId);
            if(!$review||!DynamicFormService::answers($db,(int)$submissionId))self::delegateLegacy($route,$basePath);
            if($_SERVER['REQUEST_METHOD']==='POST')self::handleReview($db,$user,(int)$submissionId,$basePath);
            self::reviewPage($db,$basePath,$user,$review);
        }
        self::delegateLegacy($route,$basePath);
    }

    private static function handleBuilderPost(PDO $db,array $user,int $formId,string $basePath):never
    {
        self::csrf();$action=(string)($_POST['action']??'');
        try{
            if(!$formId||!self::form($db,$formId))throw new RuntimeException('Choose an existing form before editing its fields.');
            $db->beginTransaction();
            if($action==='save_field'){$fieldId=filter_input(INPUT_POST,'field_id',FILTER_VALIDATE_INT)?:0;$saved=DynamicFormService::saveField($db,$formId,(int)$fieldId,$_POST);$version=DynamicFormService::bumpVersion($db,$formId);self::audit($db,(int)$user['id'],$fieldId?'form.field_updated':'form.field_created','form_field',$saved,'Updated dynamic form definition.',['form_id'=>$formId,'definition_version'=>$version]);}
            elseif($action==='toggle_field'){$fieldId=filter_input(INPUT_POST,'field_id',FILTER_VALIDATE_INT)?:0;DynamicFormService::toggleField($db,$formId,(int)$fieldId);$version=DynamicFormService::bumpVersion($db,$formId);self::audit($db,(int)$user['id'],'form.field_toggled','form_field',(int)$fieldId,'Changed dynamic form field availability.',['form_id'=>$formId,'definition_version'=>$version]);}
            else throw new RuntimeException('Choose a valid form-builder action.');
            $db->commit();self::flash('success','Form fields updated.');
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();self::flash('error',$e instanceof RuntimeException?$e->getMessage():'The form field could not be saved.');}
        self::redirect($basePath.'/admin/forms/builder?id='.$formId);
    }

    private static function handleSubmit(PDO $db,array $user,int $assignmentId,string $basePath):never
    {
        self::csrf();
        try{
            $assignment=self::assignment($db,(int)$user['id'],$assignmentId);if(!$assignment)throw new RuntimeException('That form is not assigned to you.');if($assignment['status']==='completed')throw new RuntimeException('This form is already complete.');
            $fields=DynamicFormService::fields($db,(int)$assignment['form_id']);if(!$fields)throw new RuntimeException('This form does not contain active fields.');$answers=DynamicFormService::validateAnswers($fields,$_POST);$snapshot=DynamicFormService::snapshot((int)$assignment['definition_version'],$fields);
            $db->beginTransaction();$existing=$db->prepare('SELECT id FROM form_submissions WHERE assignment_id=:assignment FOR UPDATE');$existing->execute(['assignment'=>$assignmentId]);$submissionId=(int)($existing->fetchColumn()?:0);
            $snapshotJson=json_encode($snapshot,JSON_THROW_ON_ERROR);
            if($submissionId){$stmt=$db->prepare("UPDATE form_submissions SET acknowledgment=1,typed_signature=NULL,response_text=NULL,definition_version=:version,definition_snapshot_json=:snapshot,status='submitted',reviewer_user_id=NULL,reviewer_note=NULL,submitted_at=CURRENT_TIMESTAMP,reviewed_at=NULL WHERE id=:id");$stmt->execute(['version'=>(int)$assignment['definition_version'],'snapshot'=>$snapshotJson,'id'=>$submissionId]);}
            else{$stmt=$db->prepare("INSERT INTO form_submissions (assignment_id,form_id,submitted_by_user_id,acknowledgment,definition_version,definition_snapshot_json,status) VALUES (:assignment,:form,:user,1,:version,:snapshot,'submitted')");$stmt->execute(['assignment'=>$assignmentId,'form'=>(int)$assignment['form_id'],'user'=>(int)$user['id'],'version'=>(int)$assignment['definition_version'],'snapshot'=>$snapshotJson]);$submissionId=(int)$db->lastInsertId();}
            DynamicFormService::writeAnswers($db,$submissionId,$answers);$next=(bool)$assignment['review_required']?'requires_review':'completed';$completed=$next==='completed'?date('Y-m-d H:i:s'):null;$db->prepare('UPDATE form_assignments SET status=:status,completed_at=:completed WHERE id=:id')->execute(['status'=>$next,'completed'=>$completed,'id'=>$assignmentId]);if($next==='completed')$db->prepare("UPDATE form_submissions SET status='approved',reviewed_at=CURRENT_TIMESTAMP WHERE id=:id")->execute(['id'=>$submissionId]);
            self::audit($db,(int)$user['id'],'form.dynamic_submitted','form_assignment',$assignmentId,'Submitted structured form response.',['form_id'=>(int)$assignment['form_id'],'submission_id'=>$submissionId,'definition_version'=>(int)$assignment['definition_version'],'field_count'=>count($fields),'resulting_status'=>$next]);$db->commit();self::flash('success','Your form response was submitted.');self::redirect($basePath.'/forms');
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();self::flash('error',$e instanceof RuntimeException?$e->getMessage():'The form could not be submitted.');self::redirect($basePath.'/forms/view?id='.$assignmentId);}
    }

    private static function handleReview(PDO $db,array $user,int $submissionId,string $basePath):never
    {
        self::csrf();$decision=(string)($_POST['decision']??'');$note=trim((string)($_POST['reviewer_note']??''));
        try{if(!in_array($decision,['approve','reject'],true))throw new RuntimeException('Choose approve or return.');if(mb_strlen($note)>2000)throw new RuntimeException('Keep the review note under 2,000 characters.');$db->beginTransaction();$stmt=$db->prepare("SELECT fs.id,fs.assignment_id,fs.submitted_by_user_id,fs.status,f.title FROM form_submissions fs JOIN forms f ON f.id=fs.form_id WHERE fs.id=:id FOR UPDATE");$stmt->execute(['id'=>$submissionId]);$row=$stmt->fetch();if(!$row||$row['status']!=='submitted')throw new RuntimeException('That submission is no longer awaiting review.');$approved=$decision==='approve';$db->prepare('UPDATE form_submissions SET status=:status,reviewer_user_id=:reviewer,reviewer_note=:note,reviewed_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['status'=>$approved?'approved':'rejected','reviewer'=>(int)$user['id'],'note'=>$note!==''?$note:null,'id'=>$submissionId]);$db->prepare('UPDATE form_assignments SET status=:status,completed_at=:completed WHERE id=:id')->execute(['status'=>$approved?'completed':'missing','completed'=>$approved?date('Y-m-d H:i:s'):null,'id'=>(int)$row['assignment_id']]);self::notify($db,(int)$row['submitted_by_user_id'],'form_review',$submissionId,$approved?'Form approved · '.$row['title']:'Form needs another look · '.$row['title'],$approved?'Your submitted form was reviewed and approved.':'Your submitted form was returned for an update.'.($note!==''?' Reviewer note: '.$note:''),'/forms/view?id='.(int)$row['assignment_id']);self::audit($db,(int)$user['id'],$approved?'form.approved':'form.rejected','form_submission',$submissionId,$approved?'Approved structured form.':'Returned structured form for correction.',['assignment_id'=>(int)$row['assignment_id'],'reviewer_note'=>$note!==''?$note:null]);$db->commit();self::flash('success',$approved?'Form approved.':'Form returned to the assignee.');self::redirect($basePath.'/admin/forms');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();self::flash('error',$e instanceof RuntimeException?$e->getMessage():'The review decision could not be saved.');self::redirect($basePath.'/admin/forms/review?id='.$submissionId);}
    }

    private static function builderPage(PDO $db,string $basePath,array $user,?array $form):never
    {
        $url=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=self::takeFlash();$fields=$form?DynamicFormService::fields($db,(int)$form['id'],false):[];$editId=filter_input(INPUT_GET,'field',FILTER_VALIDATE_INT)?:0;$editing=null;foreach($fields as $f)if((int)$f['id']===(int)$editId)$editing=$f;
        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Form builder · CTSMD Connect</title><link rel="stylesheet" href="<?= $url('/assets/css/app.css') ?>"><link rel="stylesheet" href="<?= $url('/assets/css/unified-navigation.css') ?>"><link rel="stylesheet" href="<?= $url('/assets/css/dynamic-forms.css') ?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/forms/builder',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Forms','Dynamic form builder',$basePath);?><div class="df-page"><?php if($flash):?><div class="df-flash <?= $e($flash['type']) ?>"><?= $e($flash['message']) ?></div><?php endif;?><?php if(!$form):?><section class="df-empty"><h2>Choose a form to build.</h2><p>Open Forms Operations and choose Builder beside an existing form.</p><a class="button" href="<?= $url('/admin/forms/manage') ?>">Forms Operations</a></section><?php else:?><section class="df-hero"><div><small>DEFINITION VERSION <?= (int)$form['definition_version'] ?></small><h2><?= $e($form['title']) ?></h2><p>Add structured questions without changing the existing assignment/review workflow.</p></div><a href="<?= $url('/admin/forms/manage/edit?id='.(int)$form['id']) ?>">Form settings →</a></section><div class="df-layout"><section class="df-fields"><header><h3>Fields</h3><span><?= count(array_filter($fields,static fn($f)=>(bool)$f['active'])) ?> active</span></header><?php if(!$fields):?><div class="df-empty compact"><b>No structured fields yet.</b></div><?php endif;?><?php foreach($fields as $f):?><article class="df-field<?= !$f['active']?' inactive':'' ?>"><div><small><?= $e(str_replace('_',' ',strtoupper($f['field_type']))) ?> · <?= $f['required']?'REQUIRED':'OPTIONAL' ?></small><h4><?= $e($f['label']) ?></h4><p><?= $e((string)($f['help_text']??'')) ?></p><?php if($f['options']):?><em><?= $e(implode(' · ',$f['options'])) ?></em><?php endif;?></div><footer><a href="<?= $url('/admin/forms/builder?id='.(int)$form['id'].'&field='.(int)$f['id']) ?>">Edit</a><form method="post"><input type="hidden" name="csrf_token" value="<?= $e((string)$_SESSION['dynamic_forms_csrf']) ?>"><input type="hidden" name="form_id" value="<?= (int)$form['id'] ?>"><input type="hidden" name="field_id" value="<?= (int)$f['id'] ?>"><button name="action" value="toggle_field" type="submit"><?= $f['active']?'Deactivate':'Reactivate' ?></button></form></footer></article><?php endforeach;?></section><form class="df-editor" method="post"><input type="hidden" name="csrf_token" value="<?= $e((string)$_SESSION['dynamic_forms_csrf']) ?>"><input type="hidden" name="form_id" value="<?= (int)$form['id'] ?>"><input type="hidden" name="field_id" value="<?= (int)($editing['id']??0) ?>"><input type="hidden" name="action" value="save_field"><small><?= $editing?'EDIT FIELD':'ADD FIELD' ?></small><label>Question / label<input name="label" maxlength="255" required value="<?= $e((string)($editing['label']??'')) ?>"></label><label>Field type<select name="field_type"><?php foreach(DynamicFormService::FIELD_TYPES as $type):?><option value="<?= $e($type) ?>"<?= ($editing['field_type']??'')===$type?' selected':'' ?>><?= $e(ucwords(str_replace('_',' ',$type))) ?></option><?php endforeach;?></select></label><label>Help text<textarea name="help_text" rows="3" maxlength="1000"><?= $e((string)($editing['help_text']??'')) ?></textarea></label><label>Choice options <small>one per line; used by choice fields</small><textarea name="options_text" rows="5"><?= $e($editing&&$editing['options']?implode("\n",$editing['options']):'') ?></textarea></label><div class="df-pair"><label>Field key<input name="field_key" maxlength="100" value="<?= $e((string)($editing['field_key']??'')) ?>" placeholder="auto-generated"></label><label>Order<input type="number" name="sort_order" value="<?= (int)($editing['sort_order']??0) ?>"></label></div><label class="df-check"><input type="checkbox" name="required" value="1"<?= !empty($editing['required'])?' checked':'' ?>><span>Required field</span></label><button class="button" type="submit"><?= $editing?'Save field':'Add field' ?></button></form></div><?php endif;?></div></main></div></body></html><?php exit;
    }

    private static function fillPage(PDO $db,string $basePath,array $user,array $assignment):never
    {
        $url=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=self::takeFlash();$fields=DynamicFormService::fields($db,(int)$assignment['form_id']);$answers=$assignment['submission_id']?DynamicFormService::answers($db,(int)$assignment['submission_id']):[];$prior=[];foreach($answers as $a)$prior[$a['field_key']]=$a['answer'];$locked=$assignment['status']==='completed'||$assignment['status']==='requires_review';
        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($assignment['title']) ?> · CTSMD Connect</title><link rel="stylesheet" href="<?= $url('/assets/css/app.css') ?>"><link rel="stylesheet" href="<?= $url('/assets/css/unified-navigation.css') ?>"><link rel="stylesheet" href="<?= $url('/assets/css/dynamic-forms.css') ?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/forms',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Forms',$assignment['title'],$basePath);?><div class="df-page"><?php if($flash):?><div class="df-flash <?= $e($flash['type']) ?>"><?= $e($flash['message']) ?></div><?php endif;?><section class="df-form-head"><small><?= $e(strtoupper($assignment['form_type'])) ?> · VERSION <?= (int)$assignment['definition_version'] ?></small><h2><?= $e($assignment['title']) ?></h2><p><?= nl2br($e((string)$assignment['instructions'])) ?></p><?php if($assignment['production_title']):?><span><?= $e($assignment['production_title']) ?></span><?php endif;?></section><form class="df-fill" method="post"><input type="hidden" name="csrf_token" value="<?= $e((string)$_SESSION['dynamic_forms_csrf']) ?>"><input type="hidden" name="assignment_id" value="<?= (int)$assignment['id'] ?>"><?php foreach($fields as $f):$key=$f['field_key'];$value=$prior[$key]??null;?><fieldset><legend><?= $e($f['label']) ?><?= $f['required']?' *':'' ?></legend><?php if($f['help_text']):?><p><?= $e($f['help_text']) ?></p><?php endif;?><?php if($f['field_type']==='long_text'):?><textarea name="field[<?= $e($key) ?>]" rows="6"<?= $f['required']?' required':'' ?><?= $locked?' disabled':'' ?>><?= $e((string)$value) ?></textarea><?php elseif($f['field_type']==='single_choice'):?><?php foreach($f['options'] as $o):?><label class="df-option"><input type="radio" name="field[<?= $e($key) ?>]" value="<?= $e($o) ?>"<?= $value===$o?' checked':'' ?><?= $locked?' disabled':'' ?>><span><?= $e($o) ?></span></label><?php endforeach;?><?php elseif($f['field_type']==='multiple_choice'):?><?php foreach($f['options'] as $o):?><label class="df-option"><input type="checkbox" name="field[<?= $e($key) ?>][]" value="<?= $e($o) ?>"<?= is_array($value)&&in_array($o,$value,true)?' checked':'' ?><?= $locked?' disabled':'' ?>><span><?= $e($o) ?></span></label><?php endforeach;?><?php elseif($f['field_type']==='acknowledgment'):?><label class="df-option"><input type="checkbox" name="field[<?= $e($key) ?>]" value="1"<?= $value?' checked':'' ?><?= $locked?' disabled':'' ?>><span>I acknowledge this statement.</span></label><?php else:?><input type="<?= $f['field_type']==='date'?'date':'text' ?>" name="field[<?= $e($key) ?>]" value="<?= $e((string)$value) ?>"<?= $f['required']?' required':'' ?><?= $locked?' disabled':'' ?><?= $f['field_type']==='signature'?' autocomplete="name"':'' ?>><?php endif;?></fieldset><?php endforeach;?><?php if(!$locked):?><footer><a href="<?= $url('/forms') ?>">Cancel</a><button class="button" type="submit">Submit form</button></footer><?php else:?><div class="df-status"><b><?= $e(ucwords(str_replace('_',' ',$assignment['status']))) ?></b><span><?= $assignment['status']==='requires_review'?'Your response is waiting for staff review.':'This form is complete.' ?></span></div><?php endif;?></form></div></main></div></body></html><?php exit;
    }

    private static function reviewPage(PDO $db,string $basePath,array $user,array $review):never
    {
        $url=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=self::takeFlash();$answers=DynamicFormService::answers($db,(int)$review['id']);
        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review <?= $e($review['title']) ?> · CTSMD Connect</title><link rel="stylesheet" href="<?= $url('/assets/css/app.css') ?>"><link rel="stylesheet" href="<?= $url('/assets/css/unified-navigation.css') ?>"><link rel="stylesheet" href="<?= $url('/assets/css/dynamic-forms.css') ?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/forms/review',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Forms','Review submission',$basePath);?><div class="df-page"><?php if($flash):?><div class="df-flash <?= $e($flash['type']) ?>"><?= $e($flash['message']) ?></div><?php endif;?><section class="df-review-head"><small>VERSION <?= (int)$review['definition_version'] ?> · <?= $e(strtoupper($review['status'])) ?></small><h2><?= $e($review['title']) ?></h2><p><?= $e($review['assignee']) ?> · submitted <?= $e(date('M j, Y · g:i A',strtotime($review['submitted_at']))) ?></p></section><section class="df-answer-list"><?php foreach($answers as $a):?><article><small><?= $e(str_replace('_',' ',strtoupper($a['field_type']))) ?></small><h3><?= $e($a['field_label']) ?></h3><p><?php if(is_array($a['answer'])):?><?= $e(implode(', ',$a['answer'])) ?><?php elseif(is_bool($a['answer'])):?><?= $a['answer']?'Acknowledged':'Not acknowledged' ?><?php else:?><?= nl2br($e((string)$a['answer'])) ?><?php endif;?></p></article><?php endforeach;?></section><?php if($review['status']==='submitted'):?><form class="df-review-form" method="post"><input type="hidden" name="csrf_token" value="<?= $e((string)$_SESSION['dynamic_forms_csrf']) ?>"><input type="hidden" name="submission_id" value="<?= (int)$review['id'] ?>"><label>Reviewer note<textarea name="reviewer_note" rows="4" maxlength="2000"></textarea></label><footer><button name="decision" value="reject" type="submit">Return for changes</button><button class="button" name="decision" value="approve" type="submit">Approve</button></footer></form><?php endif;?></div></main></div></body></html><?php exit;
    }

    private static function form(PDO $db,int $id):?array{if($id<1)return null;$s=$db->prepare('SELECT id,production_id,title,form_type,instructions,completion_mode,review_required,definition_version,active FROM forms WHERE id=:id LIMIT 1');$s->execute(['id'=>$id]);return $s->fetch()?:null;}
    private static function assignment(PDO $db,int $userId,int $id):?array{if($id<1)return null;$s=$db->prepare("SELECT fa.id,fa.status,fa.due_at,fa.completed_at,fa.production_id,f.id form_id,f.title,f.form_type,f.instructions,f.review_required,f.definition_version,p.title production_title,fs.id submission_id FROM form_assignments fa JOIN forms f ON f.id=fa.form_id LEFT JOIN productions p ON p.id=fa.production_id LEFT JOIN form_submissions fs ON fs.assignment_id=fa.id WHERE fa.id=:id AND fa.user_id=:user AND f.active=1 LIMIT 1");$s->execute(['id'=>$id,'user'=>$userId]);return $s->fetch()?:null;}
    private static function reviewItem(PDO $db,int $id):?array{if($id<1)return null;$s=$db->prepare("SELECT fs.id,fs.assignment_id,fs.status,fs.definition_version,fs.submitted_at,f.title,f.form_type,CONCAT(u.first_name,' ',u.last_name) assignee FROM form_submissions fs JOIN forms f ON f.id=fs.form_id JOIN users u ON u.id=fs.submitted_by_user_id WHERE fs.id=:id LIMIT 1");$s->execute(['id'=>$id]);return $s->fetch()?:null;}
    private static function csrf():void{if(!hash_equals((string)($_SESSION['dynamic_forms_csrf']??''),(string)($_POST['csrf_token']??'')))throw new RuntimeException('Your session token expired. Please try again.');}
    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $meta):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:meta)');$s->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'meta'=>json_encode($meta,JSON_THROW_ON_ERROR)]);}
    private static function notify(PDO $db,int $recipient,string $sourceType,int $sourceId,string $title,string $body,string $path):void{$s=$db->prepare('INSERT INTO app_notifications (recipient_user_id,source_type,source_id,title,body,action_path) VALUES (:recipient,:type,:source,:title,:body,:path)');$s->execute(['recipient'=>$recipient,'type'=>$sourceType,'source'=>$sourceId,'title'=>$title,'body'=>$body,'path'=>$path]);}
    private static function flash(string $type,string $message):void{$_SESSION['dynamic_forms_flash']=['type'=>$type,'message'=>$message];}
    private static function takeFlash():?array{$f=$_SESSION['dynamic_forms_flash']??null;unset($_SESSION['dynamic_forms_flash']);return $f;}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function delegateLegacy(string $route,string $basePath):never{require_once __DIR__.'/FormExperience.php';FormExperience::render($route,$basePath);}
    private static function forbidden(string $basePath,array $user):never{http_response_code(403);echo 'Restricted';exit;}
}
